package com.pebo.nfcprobe20261015.protocol

import com.pebo.nfcprobe20261015.transport.*
import org.junit.Assert.*
import org.junit.Test
import java.util.Random

class ProtocolTest {
 private fun <T> ok(result:ParseResult<T>):T {assertTrue(result.toString(),result is ParseResult.Ok);return (result as ParseResult.Ok).value}
 private fun error(result:ParseResult<*>,kind:ErrorKind){assertTrue(result.toString(),result is ParseResult.Error);assertEquals(kind,(result as ParseResult.Error).kind)}
 private fun ping()=PacketCodec.encode(Packet(PeboCommand.PING,0,byteArrayOf()))
 private fun validConfig()=PeboConfig(8,true,listOf(ReminderPeriod(0,540,600,0),ReminderPeriod(1,600,660,1)))
 private fun status()=DeviceStatus(0xFEDCBA98L,2800,75,0,3,1,2,8,1,0x80000000L,0x1234)
 private fun body(client:PeboClient,command:PeboCommand,request:RequestBody=RequestBody.Empty):ResponseBody?=ok(client.execute(command,request).result).also{assertEquals(PeboStatusCode.OK,it.status)}.body
 @Test fun crcStandardCheckVector(){assertEquals(0x29B1,Crc16CcittFalse.compute("123456789".toByteArray(Charsets.US_ASCII)));assertEquals(0xFFFF,Crc16CcittFalse.compute(byteArrayOf()))}
 @Test fun packetEncodeGoldenIndependentPythonBinascii(){assertEquals("50 42 01 08 00 00 7A F4",PacketCodec.hex(ping()))}
 @Test fun packetDecodeGolden(){val packet=ok(PacketCodec.decode(ping()));assertEquals(PeboCommand.PING,packet.command);assertEquals(0,packet.sequence);assertFalse(packet.response);assertArrayEquals(byteArrayOf(),packet.payload)}
 @Test fun packetRoundTripAllCommandsBothDirections(){for(command in PeboCommand.entries)for(response in listOf(false,true)){val payload=byteArrayOf(0,1,0xFE.toByte());val result=ok(PacketCodec.decode(PacketCodec.encode(Packet(command,255,payload,response)),command,255,response));assertEquals(command,result.command);assertArrayEquals(payload,result.payload)}}
 @Test fun invalidMagic(){error(PacketCodec.decode(ping().apply{this[0]=0}),ErrorKind.MAGIC)}
 @Test fun invalidVersion(){error(PacketCodec.decode(ping().apply{this[2]=2}),ErrorKind.VERSION)}
 @Test fun invalidPayloadLength(){error(PacketCodec.decode(ping().apply{this[5]=1}),ErrorKind.LENGTH)}
 @Test fun corruptCrc(){error(PacketCodec.decode(ping().apply{this[lastIndex]=(this[lastIndex].toInt() xor 1).toByte()}),ErrorKind.CRC)}
 @Test fun truncatedPacket(){for(length in 0..7)error(PacketCodec.decode(ping().take(length).toByteArray()),ErrorKind.LENGTH)}
 @Test fun oversizedPacket(){error(PacketCodec.decode(ByteArray(257)),ErrorKind.LENGTH);assertThrows(IllegalArgumentException::class.java){PacketCodec.encode(Packet(PeboCommand.PING,0,ByteArray(249)))}}
 @Test fun maximumPayload248Produces256BytePacket(){val bytes=PacketCodec.encode(Packet(PeboCommand.PING,0,ByteArray(248)));assertEquals(256,bytes.size);assertEquals(248,ok(PacketCodec.decode(bytes)).payload.size)}
 @Test fun wrongCommandDirectionAndSequence(){val bytes=PacketCodec.encode(Packet(PeboCommand.GET_STATUS,7,byteArrayOf(0),true));error(PacketCodec.decode(bytes,PeboCommand.PING),ErrorKind.COMMAND);error(PacketCodec.decode(bytes,expectedSequence=6),ErrorKind.SEQUENCE);error(PacketCodec.decode(bytes,expectedResponse=false),ErrorKind.COMMAND)}
 @Test fun unknownCommandWithValidCrc(){val bytes=ping().copyOfRange(0,6).apply{this[3]=0x09};error(PacketCodec.decode(bytes+LittleEndian.u16(Crc16CcittFalse.compute(bytes))),ErrorKind.COMMAND)}
 @Test fun littleEndianUnsignedAndSigned(){assertArrayEquals(byteArrayOf(0x34,0x12),LittleEndian.u16(0x1234));assertEquals(0xFFFFFFFFL,Reader(LittleEndian.u32(0xFFFFFFFFL)).u32());for(offset in listOf(-32768,-480,0,480,32767))assertEquals(offset,Reader(LittleEndian.i16(offset)).i16())}
 @Test fun setTimeRequest(){val bytes=PayloadCodec.encodeRequest(PeboCommand.SET_TIME,RequestBody.SetTime(0xFFFFFFFFL,480));assertEquals("FF FF FF FF E0 01",PacketCodec.hex(bytes));assertEquals(RequestBody.SetTime(0xFFFFFFFFL,480),ok(PayloadCodec.decodeRequest(PeboCommand.SET_TIME,bytes)))}
 @Test fun deviceInfoPayloadRoundTrip(){val info=DeviceInfo((1..8).toList(),1,2,3,4,5,1,0xBEEF);val encoded=PayloadCodec.encodeReply(PeboCommand.GET_DEVICE_INFO,PeboReply(PeboStatusCode.OK,info));assertEquals(17,encoded.size);assertEquals(info,ok(PayloadCodec.decodeReply(PeboCommand.GET_DEVICE_INFO,encoded)).body)}
 @Test fun deviceStatusOffsetsAndDistinctCounts(){val encoded=PayloadCodec.encodeReply(PeboCommand.GET_STATUS,PeboReply(PeboStatusCode.OK,status()));assertEquals(20,encoded.size);assertEquals(3,encoded[9].toInt());assertEquals(1,encoded[10].toInt());assertEquals("98 BA DC FE",PacketCodec.hex(encoded.copyOfRange(1,5)));assertEquals(status(),ok(PayloadCodec.decodeReply(PeboCommand.GET_STATUS,encoded)).body)}
 @Test fun statusRangesRejectMalformed(){val good=PayloadCodec.encodeReply(PeboCommand.GET_STATUS,PeboReply(PeboStatusCode.OK,status()));for((offset,value) in listOf(7 to 101,13 to 9,10 to 3,11 to 17)){val changed=good.copyOf().apply{this[offset]=value.toByte()};error(PayloadCodec.decodeReply(PeboCommand.GET_STATUS,changed),ErrorKind.VALIDATION)}}
 @Test fun configRoundTripAndGetStatusPrefix(){val cfg=validConfig();assertEquals(cfg,ok(PayloadCodec.decodeConfig(PayloadCodec.encodeConfig(cfg))));val response=PayloadCodec.encodeReply(PeboCommand.GET_CONFIG,PeboReply(PeboStatusCode.OK,cfg));assertEquals(0,response[0].toInt());assertEquals(cfg,ok(PayloadCodec.decodeReply(PeboCommand.GET_CONFIG,response)).body)}
 @Test fun configMaximum16AdjacentPeriods(){val cfg=PeboConfig(16,true,List(16){ReminderPeriod(it,it*60,(it+1)*60,0)});assertTrue(ConfigValidation.validate(cfg).isEmpty());assertEquals(cfg,ok(PayloadCodec.decodeConfig(PayloadCodec.encodeConfig(cfg))))}
 @Test fun configRejectsTooManyOverlappingCrossMidnightAndBadMinutes(){val good=validConfig();for(cfg in listOf(good.copy(periods=List(17){ReminderPeriod(it,0,1,0)}),good.copy(periods=listOf(ReminderPeriod(0,600,540,0))),good.copy(periods=listOf(ReminderPeriod(0,-1,60,0))),good.copy(periods=listOf(ReminderPeriod(0,0,1441,0))),good.copy(periods=listOf(ReminderPeriod(0,540,650,0),ReminderPeriod(1,600,660,0))))){assertTrue(ConfigValidation.validate(cfg).isNotEmpty())}}
 @Test fun configUniqueIdsZeroLengthAndBoundary(){val good=validConfig();assertTrue(ConfigValidation.validate(good.copy(periods=listOf(ReminderPeriod(0,0,60,0),ReminderPeriod(0,60,120,0)))).isNotEmpty());assertTrue(ConfigValidation.validate(good.copy(periods=listOf(ReminderPeriod(0,0,0,0)))).isNotEmpty());assertTrue(ConfigValidation.validate(good.copy(periods=listOf(ReminderPeriod(15,1439,1440,255)))).isEmpty())}
 @Test fun configMalformedCountEnableReservedTruncatedTrailing(){val bytes=PayloadCodec.encodeConfig(validConfig());for(changed in listOf(bytes.copyOf().apply{this[1]=17},bytes.copyOf().apply{this[2]=2},bytes.copyOf().apply{this[3]=1},bytes.dropLast(1).toByteArray(),bytes+byteArrayOf(0))){assertTrue(PayloadCodec.decodeConfig(changed) is ParseResult.Error)}}
 @Test fun drinkRecordSixByteRoundTrip(){for(period in listOf(0,15,255)){val record=DrinkRecord(0xFFFFFFFFL,period,15);val bytes=PayloadCodec.encodeDrink(record);assertEquals(6,bytes.size);assertEquals(record,ok(PayloadCodec.decodeDrink(bytes)));assertTrue(record.validDrink);assertTrue(record.periodCompletionEvent)}}
 @Test fun drinkRejectsReservedFlagsInvalidPeriodAndLengths(){for(bytes in listOf(ByteArray(5),ByteArray(7),byteArrayOf(0,0,0,0,16,0),byteArrayOf(0,0,0,0,0,16))){assertTrue(PayloadCodec.decodeDrink(bytes) is ParseResult.Error)}}
 @Test fun responseStatusErrorsNotMistakenForData(){for(code in PeboStatusCode.entries.filter{it!=PeboStatusCode.OK}){val parsed=ok(PayloadCodec.decodeReply(PeboCommand.GET_STATUS,byteArrayOf(code.code.toByte())));assertEquals(code,parsed.status);assertNull(parsed.body)};assertTrue(PayloadCodec.decodeReply(PeboCommand.GET_STATUS,byteArrayOf(4,0)) is ParseResult.Error);assertTrue(PayloadCodec.decodeReply(PeboCommand.PING,byteArrayOf(99)) is ParseResult.Error)}
 @Test fun emptyTruncatedTrailingReplyRejected(){for(command in PeboCommand.entries){assertTrue(PayloadCodec.decodeReply(command,byteArrayOf()) is ParseResult.Error)};assertTrue(PayloadCodec.decodeReply(PeboCommand.GET_DEVICE_INFO,byteArrayOf(0)) is ParseResult.Error);assertTrue(PayloadCodec.decodeReply(PeboCommand.PING,byteArrayOf(0,0)) is ParseResult.Error)}
 @Test fun allEmptyRequestsRejectTrailingData(){for(command in listOf(PeboCommand.PING,PeboCommand.GET_STATUS,PeboCommand.GET_CONFIG,PeboCommand.GET_DEVICE_INFO,PeboCommand.CLEAR_HISTORY)){assertEquals(RequestBody.Empty,ok(PayloadCodec.decodeRequest(command,byteArrayOf())));assertTrue(PayloadCodec.decodeRequest(command,byteArrayOf(1)) is ParseResult.Error)}}
 @Test fun samplePagination85As40Plus40Plus5(){val client=PeboClient(SamplePeboTransport());var start=0;val counts=mutableListOf<Int>();val all=mutableListOf<DrinkRecord>();do{val report=client.execute(PeboCommand.GET_HISTORY,RequestBody.History(start,255));assertTrue(report.rx!!.size<=256);val page=ok(report.result).body as HistoryPage;counts.add(page.records.size);all.addAll(page.records);start=page.nextIndex}while(page.hasMore);assertEquals(listOf(40,40,5),counts);assertEquals(85,all.size)}
 @Test fun requestedPageCountAndEnd(){val client=PeboClient(SamplePeboTransport());assertEquals(2,(body(client,PeboCommand.GET_HISTORY,RequestBody.History(0,2)) as HistoryPage).records.size);val page=body(client,PeboCommand.GET_HISTORY,RequestBody.History(85,40)) as HistoryPage;assertFalse(page.hasMore);assertTrue(page.records.isEmpty());assertEquals(PeboStatusCode.INVALID_DATA,ok(client.execute(PeboCommand.GET_HISTORY,RequestBody.History(86,40)).result).status)}
 @Test fun malformedHistoryPageRejected(){val bad=byteArrayOf(0)+LittleEndian.u16(0)+LittleEndian.u16(1)+byteArrayOf(0);assertTrue(PayloadCodec.decodeReply(PeboCommand.GET_HISTORY,bad) is ParseResult.Error);assertTrue(PayloadCodec.decodeReply(PeboCommand.GET_HISTORY,byteArrayOf(0,0,0,0,0,41)) is ParseResult.Error)}
 @Test fun sampleConfigAndTimeAcksRoundTrip(){val client=PeboClient(SamplePeboTransport());val cfg=validConfig().copy(dailyTarget=12);assertEquals(Acknowledgement,body(client,PeboCommand.SET_CONFIG,RequestBody.Config(cfg)));assertEquals(cfg,body(client,PeboCommand.GET_CONFIG));assertEquals(Acknowledgement,body(client,PeboCommand.SET_TIME,RequestBody.SetTime(0xFFFFFFFFL,-480)));assertEquals(0xFFFFFFFFL,(body(client,PeboCommand.GET_STATUS) as DeviceStatus).deviceUnixTime);assertEquals(Acknowledgement,body(client,PeboCommand.PING))}
 @Test fun sampleClearHistoryAndZeroPeriodConfig(){val client=PeboClient(SamplePeboTransport());body(client,PeboCommand.CLEAR_HISTORY);assertEquals(0,(body(client,PeboCommand.GET_HISTORY,RequestBody.History(0,40)) as HistoryPage).totalRecords);body(client,PeboCommand.SET_CONFIG,RequestBody.Config(PeboConfig(0,false,emptyList())));assertEquals(0,(body(client,PeboCommand.GET_STATUS) as DeviceStatus).completedReminderPeriodCount)}
 @Test fun invalidRequestDoesNotCallTransport(){var calls=0;val client=PeboClient(object:PeboPacketTransport{override val sourceLabel="test";override fun exchange(requestPacket:ByteArray):ByteArray{calls++;return byteArrayOf()}});assertTrue(client.execute(PeboCommand.GET_HISTORY,RequestBody.History(-1,0)).result is ParseResult.Error);assertEquals(0,calls)}
 @Test fun unboundRealTransportReturnsExplicitFailureNoRx(){val report=PeboClient(UnboundNfcVPacketTransport()).execute(PeboCommand.GET_STATUS);assertNull(report.rx);assertNotNull(report.error);assertTrue(report.result is ParseResult.Error);assertTrue(report.source.contains("真實"))}
 @Test fun clientRejectsMismatchedSequence(){val client=PeboClient(object:PeboPacketTransport{override val sourceLabel="bad";override fun exchange(requestPacket:ByteArray):ByteArray{val request=ok(PacketCodec.decode(requestPacket));return PacketCodec.encode(Packet(request.command,(request.sequence+1)and 255,byteArrayOf(0),true))}});error(client.execute(PeboCommand.PING).result,ErrorKind.SEQUENCE)}
 @Test fun sequenceWrapsAt255(){val client=PeboClient(SamplePeboTransport());repeat(258){i -> val report=client.execute(PeboCommand.PING);assertEquals(i and 255,ok(PacketCodec.decode(report.tx)).sequence);assertTrue(report.result is ParseResult.Ok)}}
 @Test fun randomizedMalformedPacketsAndPayloadsDoNotThrow(){val random=Random(42);repeat(2000){val bytes=ByteArray(random.nextInt(300));random.nextBytes(bytes);PacketCodec.decode(bytes);PayloadCodec.decodeConfig(bytes);PayloadCodec.decodeDrink(bytes);for(command in PeboCommand.entries)PayloadCodec.decodeReply(command,bytes)}}
}